import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    arr = list(map(int, data[1:1+n]))
    x = int(data[1+n])

    first = -1
    left, right = 0, n - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] >= x:
            first = mid
            right = mid - 1
        else:
            left = mid + 1

    if first == -1 or arr[first] != x:
        print("-1 -1")
        return

    last = first
    left, right = first, n - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] <= x:
            last = mid
            left = mid + 1
        else:
            right = mid - 1

    print(f"{first} {last}")

if __name__ == "__main__":
    main()
